-- SQL Server reference schema. The Flask application uses the same relational design through SQLAlchemy.
CREATE TABLE Categories (CategoryId INT IDENTITY PRIMARY KEY, Name NVARCHAR(80) NOT NULL UNIQUE, TransactionType NVARCHAR(10) NOT NULL CHECK (TransactionType IN ('Income','Expense')), Description NVARCHAR(255) NULL, IsActive BIT NOT NULL DEFAULT 1, CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Transactions (TransactionId INT IDENTITY PRIMARY KEY, CategoryId INT NOT NULL FOREIGN KEY REFERENCES Categories(CategoryId), TransactionDate DATE NOT NULL, TransactionType NVARCHAR(10) NOT NULL CHECK (TransactionType IN ('Income','Expense')), Description NVARCHAR(200) NOT NULL, Amount DECIMAL(18,2) NOT NULL CHECK (Amount > 0), PaymentMethod NVARCHAR(60), Notes NVARCHAR(MAX), IsDeleted BIT NOT NULL DEFAULT 0, CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE INDEX IX_Transactions_Date ON Transactions(TransactionDate); CREATE INDEX IX_Transactions_Category ON Transactions(CategoryId);
CREATE TABLE Budgets (BudgetId INT IDENTITY PRIMARY KEY, CategoryId INT NOT NULL FOREIGN KEY REFERENCES Categories(CategoryId), BudgetMonth TINYINT NOT NULL CHECK (BudgetMonth BETWEEN 1 AND 12), BudgetYear SMALLINT NOT NULL, Amount DECIMAL(18,2) NOT NULL CHECK (Amount >= 0), CONSTRAINT UQ_Budget_Category_Period UNIQUE(CategoryId, BudgetMonth, BudgetYear));
